/**
 * A machine-readable error code from the REST API's `ApiError.code` field.
 *
 * **Not** the vocabulary of the 409 admission/quota body: `DenyReason` keys its
 * discriminant on `code` too, and that is all the two share — its values
 * (`ram_headroom_exceeded`, `user_vcpu_quota_exceeded`, …) are a separate closed
 * catalogue and none of them appears here. This text is published in
 * `sdk/openapi.yaml`, and an earlier version said the two "share the same wire
 * vocabulary", which would lead a client author to type every `code` as this
 * enum and be wrong on every 409.
 *
 * `snake_case`, `<subject>_<condition>`: the subject is
 * the thing that went wrong, not the endpoint.
 */
export type ErrorCode = 'validation_failed' | 'internal_error' | 'resource_not_found' | 'unavailable' | 'rate_limited' | 'database_unavailable' | 'invalid_config' | 'CLI_TOO_OLD' | 'vm_not_found' | 'vm_name_taken' | 'invalid_vm_name' | 'capacity_exhausted' | 'invalid_state_transition' | 'vm_access_denied' | 'admin_required' | 'too_many_tags' | 'tag_reserved_prefix' | 'tag_invalid_key' | 'tag_invalid_value' | 'tag_invalid' | 'team_has_vms' | 'team_not_found' | 'user_not_provisioned' | 'user_never_signed_in' | 'image_rejected' | 'unknown_image' | 'secret_name_invalid' | 'checkpoint_conflict' | 'clone_source_not_found' | 'wake_target_not_found' | 'disk_rollback_not_named' | 'feature_disabled' | 'port_not_allowed' | 'port_not_primary' | 'primary_port_not_removable' | 'identity_missing' | 'identity_invalid' | 'credential_missing' | 'credential_invalid' | 'credential_expired' | 'scope_denied' | 'sudo_required' | 'ticket_required' | 'user_disabled' | 'platform_not_available' | 'cli_distribution_not_configured' | 'webhook_not_found' | 'webhook_access_denied' | 'webhook_subscription_disabled' | 'storage_error' | 'crypto_error' | 'guest_agent_too_old' | 'file_not_found' | 'file_not_regular' | 'file_path_denied' | 'file_too_large' | 'guest_disk_full' | 'client_address_denied';

/**
 * Data of the terminal `exit` event of `POST /vms/{name}/exec`.
 *
 * `timed_out` is `true` when the command ran past `timeout_secs`: the guest
 * killed the command's whole process group and `code` is 124. A command
 * that exits 124 on its own has `timed_out: false`. A server built before
 * the field sends `{"code": N}` only; read its absence as `false`.
 */
export type ExecExit = {
    /**
     * The command's exit status; 124 when `timed_out`, -1 when it was
     * killed by a signal for any other reason.
     */
    code: number;
    /**
     * The exec deadline killed the command.
     */
    timed_out?: boolean;
};

/**
 * Non-streaming exec result returned by the `--inject` path after
 * inject -> exec -> optional wipe completes.
 */
export type ExecOutputDto = {
    /**
     * The command's exit status; 124 when `timed_out`.
     */
    exit_code: number;
    stderr: string;
    stdout: string;
    /**
     * The command ran past its deadline (`timeout_secs`, default 30): the
     * guest killed its whole process group, `exit_code` is 124 and
     * `stdout`/`stderr` hold what it wrote before then. A command that
     * exits 124 on its own has `timed_out: false`.
     */
    timed_out?: boolean;
};

/**
 * POST /vms/{name}/exec request body.
 */
export type ExecRequestDto = {
    command: Array<string>;
    /**
     * Working directory for the command. A relative path resolves against
     * the home directory of the account it runs as. Default: that home
     * directory (`/root`).
     */
    cwd?: string | null;
    /**
     * Extra environment variables, set last so they win over the defaults
     * (`PATH` included). At most 128, each name at most 256 bytes with no
     * `=`; names and values must not contain NUL.
     */
    env?: {
        [key: string]: string;
    } | null;
    /**
     * Run the command through the account's login shell (`<shell> -l -c`),
     * so its profile files apply (for example tools a profile script adds
     * to `PATH`). Default `false`: the command gets a login-like
     * environment without any profile file being run.
     */
    login?: boolean | null;
    selector?: null | InjectSelector;
    /**
     * Text written to the command's stdin (as UTF-8), which is then closed,
     * so a reader sees end of input. Use it to pipe a script into an
     * interpreter (`["python3", "-"]`) or data into a command. At most
     * 1 MiB (1048576 bytes); a larger one is refused with 400 before
     * anything runs. Not together with `stdin_b64`. Without either, the
     * command's stdin is empty (`/dev/null`). Needs a guest agent of
     * protocol 10 or later; an older one refuses the exec. With `login`,
     * the login shell's profile files share this stdin, so one that reads
     * input would consume it first.
     */
    stdin?: string | null;
    /**
     * Like `stdin`, for bytes: standard base64 (with padding), decoded and
     * written byte for byte. The 1 MiB cap applies to the decoded bytes.
     * Not together with `stdin`.
     */
    stdin_b64?: string | null;
    /**
     * Seconds the command may run (default 30). Past it the guest kills the
     * command's whole process group and the stream ends with `exit`
     * `{"code": 124, "timed_out": true}`.
     */
    timeout_secs?: number | null;
    /**
     * Account to run the command as, by name in the VM's `/etc/passwd`.
     * Default: root.
     */
    user?: string | null;
};

/**
 * POST /vms/{name}/exec-with-secrets request body.
 *
 * The buffered, secrets-injected form of exec, split out of `/exec` because
 * one route cannot answer with both an SSE stream and a JSON body in any
 * describable way. `selector` is REQUIRED here — it is what the operation is
 * for — where on `ExecRequestDto` it is the optional field that used to switch
 * `/exec` between its two response shapes.
 *
 * `timeout_secs` bounds the command as it does on `ExecRequestDto`: past it
 * the guest kills the command's process group and the response is exit 124
 * with `timed_out`. The `setup_tag` wipe still runs afterwards.
 *
 * A field this operation does not define is refused with 400
 * `validation_failed` naming it, not ignored: a caller that sends an option
 * it lacks (a typo, or an exec option added after this one) would otherwise
 * get the command run without it.
 */
export type ExecWithSecretsRequest = {
    /**
     * argv, first element is the program. Must not be empty.
     */
    command: Array<string>;
    /**
     * Which of the VM's secrets to push into the guest before running.
     */
    selector: InjectSelector;
    /**
     * Seconds the command may run (default 30, at most 3600; a larger
     * value is refused with 400 `validation_failed`). Past it the guest
     * kills the command's whole process group and the result is
     * `exit_code` 124 with `timed_out: true`.
     */
    timeout_secs?: number | null;
};

/**
 * An expiry counted from now (`setVmExpiry`'s `expires_in`).
 */
export type ExpiresIn = {
    /**
     * Seconds from now until Cove deletes the VM and its disk: 3600 (one
     * hour) to 315360000 (ten years). `null` removes the expiry.
     */
    secs?: number | null;
};

/**
 * `PUT /vms/{name}/files` response body: the file as it was committed in the
 * guest.
 */
export type FileUploaded = {
    /**
     * The file's permission bits as a number (`420` is `0o644`).
     */
    mode: number;
    /**
     * The absolute guest path the file was written to.
     */
    path: string;
    /**
     * Lowercase hex SHA-256 of the bytes the server sent to the guest.
     */
    sha256: string;
    /**
     * Bytes written: always the request's `Content-Length`.
     */
    size: number;
};

/**
 * Grant result. A user grant must name someone who has signed in to this
 * Cove server at least once; a never-seen username is refused (422
 * `user_never_signed_in`) rather than answered here. `user_known` is `false`
 * when that person has no account at the access gateway right now (it was
 * deleted, say). The grant still succeeds (role assigned to targets); access
 * applies when they next sign in. Callers surface a note when it is false.
 *
 * This is the ONE `GrantShareOutcome` that gets `ToSchema`. The
 * server-side `cove_service::ops::share::GrantShareOutcome` is a stale
 * duplicate the `POST /vms/{name}/shares` handler does not serialize
 * directly — see the NOTE on that duplicate.
 */
export type GrantShareOutcome = {
    user_known: boolean;
};

/**
 * Wire body for `POST /vms/{name}/access`.
 *
 * Mirrors `cove_api_client::wire_types::GrantShareRequest`: a
 * `subject_type` discriminator ("user" | "team"),
 * the `subject_id` (username), and the `role` token ("user" |
 * "collaborator"). The handler parses + validates before delegating to
 * the service op so a malformed body surfaces as 400, not a service
 * `Validation` 422 — keeps the contract uniform with other cove
 * handlers that validate the wire shape at the edge.
 */
export type GrantShareRequest = {
    role: string;
    subject_id: string;
    subject_type: string;
};

